<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php';
if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['store_name','currency','tax_rate','phone','address'] as $k){$v=trim($_POST[$k]??'');$pdo->prepare("INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)")->execute([$k,$v]);}flash('success','Settings saved.');header("Location:index.php");exit;}
$rows=$pdo->query("SELECT setting_key,setting_value FROM settings")->fetchAll();$s=[];foreach($rows as $r)$s[$r['setting_key']]=$r['setting_value'];$page_title='Settings';require __DIR__.'/../partials/header.php';?>
<h3 class="fw-bold">Store Settings</h3><div class="card p-4 mt-3"><form method="post" class="row g-3"><div class="col-md-6"><label class="form-label">Store Name</label><input class="form-control" name="store_name" value="<?=e($s['store_name']??'ProStock Store')?>"></div><div class="col-md-6"><label class="form-label">Currency</label><input class="form-control" name="currency" value="<?=e($s['currency']??'USD')?>"></div><div class="col-md-6"><label class="form-label">Tax Rate (%)</label><input class="form-control" name="tax_rate" value="<?=e($s['tax_rate']??'0')?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=e($s['phone']??'')?>"></div><div class="col-12"><label class="form-label">Address</label><textarea class="form-control" name="address"><?=e($s['address']??'')?></textarea></div><div class="col-12"><button class="btn btn-primary">Save Settings</button></div></form></div>
